//go:build linux

// Command nettrace is a throwaway spike (DEVDESK-385, S-01): can an
// unprivileged process trace a path with UDP probes of growing TTL and read the
// ICMP Time Exceeded replies through IP_RECVERR and MSG_ERRQUEUE? It is
// standalone (standard library only), IPv4 only, and prints a report meant to
// be pasted as is. It is never merged.
package main

import (
	"context"
	"encoding/binary"
	"errors"
	"flag"
	"fmt"
	"net"
	"net/netip"
	"os"
	"runtime"
	"sort"
	"strings"
	"sync"
	"syscall"
	"time"
)

// commit is set at build time with -ldflags "-X main.commit=<sha>".
var commit = "unknown"

const (
	// ipRecvErr is IP_RECVERR; package syscall does not export it.
	ipRecvErr = 11
	// basePort is the first destination port; a probe uses basePort+ttl.
	basePort = 33434
	// hardMaxTTL is the decided maximum TTL of the spike.
	hardMaxTTL = 30
	// hardDeadline is the decided maximum duration of one trace.
	hardDeadline = 30 * time.Second

	icmpDestUnreach  = 3
	icmpTimeExceeded = 11
	icmpPortUnreach  = 3 // code, with icmpDestUnreach
	soEeOriginICMP   = 2
)

// kind is what the error queue told about one probe.
type kind int

const (
	kindSilent     kind = iota // no error before the probe timeout
	kindTimeExceed             // ICMP Time Exceeded from a router
	kindReached                // ICMP Port Unreachable from the target
	kindUnreach                // another ICMP Destination Unreachable
	kindCancelled              // the trace ended before the probe resolved
	kindSockErr                // local failure (setsockopt, send, recv)
)

func (k kind) String() string {
	switch k {
	case kindSilent:
		return "silent"
	case kindTimeExceed:
		return "time-exceeded"
	case kindReached:
		return "target-reached"
	case kindUnreach:
		return "unreachable"
	case kindCancelled:
		return "unresolved"
	default:
		return "socket-error"
	}
}

// outcome is the explicit result of a trace.
type outcome int

const (
	outReached    outcome = iota // target reached
	outTTLMax                    // target not reached, maximum TTL
	outDelay                     // target not reached, delay elapsed
	outCancelled                 // cancelled by the caller
	outInconclusv                // not used for decisions
)

func (o outcome) String() string {
	switch o {
	case outReached:
		return "target reached"
	case outTTLMax:
		return "target not reached, maximum TTL"
	case outDelay:
		return "target not reached, delay elapsed"
	case outCancelled:
		return "cancelled"
	default:
		return "inconclusive"
	}
}

type probe struct {
	TTL     int
	Kind    kind
	Addr    netip.Addr
	Latency time.Duration
	Code    int    // ICMP type/code detail for kindUnreach
	Detail  string // raw error text, never shown as a summary
	SockOpt string // setsockopt error text, empty when fine
}

type result struct {
	Target   string
	MaxTTL   int
	Timeout  time.Duration
	Duration time.Duration
	Outcome  outcome
	Probes   []probe // index ttl-1
	Hops     []probe // probes up to the target (or all)
	Pending  int     // unresolved probes when the trace ended
}

func main() {
	target := flag.String("target", "1.1.1.1", "public target (IPv4 address or name)")
	unreach := flag.String("unreachable", "192.0.2.1", "target that never answers (documentation block)")
	maxTTL := flag.Int("max-ttl", hardMaxTTL, "maximum TTL")
	timeout := flag.Duration("probe-timeout", 3*time.Second, "per-probe timeout")
	deadline := flag.Duration("deadline", hardDeadline, "whole-trace deadline")
	cycles := flag.Int("cycles", 100, "cancellation cycles for L7")
	extra := flag.String("extra-targets", "", "comma-separated extra targets traced once, to look for a silent hop (L4)")
	flag.Parse()

	if *maxTTL < 1 || *maxTTL > hardMaxTTL {
		fmt.Fprintf(os.Stderr, "max-ttl must be in 1..%d\n", hardMaxTTL)
		os.Exit(2)
	}
	if *deadline > hardDeadline {
		fmt.Fprintf(os.Stderr, "deadline is capped at %s\n", hardDeadline)
		os.Exit(2)
	}
	rep := &report{}
	rep.header(*target, *unreach, *maxTTL, *timeout, *deadline, *cycles)

	// Main trace: L1, L2, L3, L4, L6.
	main1 := trace(context.Background(), *target, *maxTTL, *timeout, *deadline)
	rep.printTrace("Main trace", main1)

	// L6 measurement: real path if it has at least 8 hops, else TTL bounded to 8.
	l6 := measureL6(main1, *target, *timeout, *deadline)
	rep.printL6(l6)

	// L5 measurements.
	l5 := measureL5(*target, *unreach, *timeout)
	rep.printL5(l5)

	// L4 candidates.
	var extras []result
	for _, t := range strings.Split(*extra, ",") {
		if t = strings.TrimSpace(t); t != "" {
			r := trace(context.Background(), t, *maxTTL, *timeout, *deadline)
			rep.printTrace("Extra trace (L4 candidate)", r)
			extras = append(extras, r)
		}
	}

	// L7.
	l7 := measureL7(*unreach, *cycles, *timeout)
	rep.printL7(l7)

	rep.verdicts(main1, l6, l5, extras, l7)
	fmt.Print(rep.String())
}

// ---------------------------------------------------------------- engine

// trace sends one UDP probe per TTL in parallel, each from its own socket, and
// reads the Time Exceeded replies from the socket error queue. It returns once
// every TTL up to the target (or up to maxTTL) is resolved, the deadline has
// passed or ctx is cancelled. Every socket is closed before it returns.
func trace(ctx context.Context, target string, maxTTL int, timeout, deadline time.Duration) result {
	start := time.Now()
	res := result{Target: target, MaxTTL: maxTTL, Timeout: timeout, Probes: make([]probe, maxTTL)}
	ctx, cancelDeadline := context.WithTimeout(ctx, deadline)
	defer cancelDeadline()
	pctx, cancelProbes := context.WithCancel(ctx)
	defer cancelProbes()

	ip, err := resolveV4(target)
	if err != nil {
		res.Probes = nil
		res.Outcome = outCancelled
		res.Hops = []probe{{Kind: kindSockErr, Detail: err.Error()}}
		return res
	}

	out := make(chan probe, maxTTL)
	var wg sync.WaitGroup
	for ttl := 1; ttl <= maxTTL; ttl++ {
		wg.Add(1)
		go func(ttl int) {
			defer wg.Done()
			out <- sendProbe(pctx, ip, ttl, timeout)
		}(ttl)
	}

	resolved := make([]bool, maxTTL+1)
	limit := maxTTL // highest TTL that must be resolved
	done := false
	for got := 0; got < maxTTL && !done; got++ {
		select {
		case p := <-out:
			res.Probes[p.TTL-1] = p
			resolved[p.TTL] = true
			if p.Kind == kindReached && p.TTL < limit {
				limit = p.TTL
			}
			done = allResolved(resolved, limit)
		case <-ctx.Done():
			done = true
		}
	}
	cancelProbes()
	wg.Wait()
	close(out)
	for p := range out { // probes that finished while shutting down
		if !resolved[p.TTL] && p.Kind != kindCancelled {
			res.Probes[p.TTL-1] = p
			resolved[p.TTL] = true
		}
	}
	res.Duration = time.Since(start)

	reached := 0
	for i := range res.Probes {
		if res.Probes[i].TTL == 0 {
			res.Probes[i] = probe{TTL: i + 1, Kind: kindCancelled}
		}
		if res.Probes[i].Kind == kindReached && (reached == 0 || i+1 < reached) {
			reached = i + 1
		}
	}
	switch {
	case reached > 0:
		res.Outcome = outReached
		res.Hops = res.Probes[:reached]
	case errors.Is(ctx.Err(), context.DeadlineExceeded):
		res.Outcome = outDelay
		res.Hops = res.Probes
	case ctx.Err() != nil:
		res.Outcome = outCancelled
		res.Hops = res.Probes
	default:
		res.Outcome = outTTLMax
		res.Hops = res.Probes
	}
	for _, p := range res.Probes {
		if p.Kind == kindCancelled {
			res.Pending++
		}
	}
	return res
}

func allResolved(resolved []bool, limit int) bool {
	for t := 1; t <= limit; t++ {
		if !resolved[t] {
			return false
		}
	}
	return true
}

func resolveV4(target string) (netip.Addr, error) {
	if a, err := netip.ParseAddr(target); err == nil {
		if !a.Is4() {
			return netip.Addr{}, fmt.Errorf("%s is not an IPv4 address", target)
		}
		return a, nil
	}
	ips, err := net.LookupIP(target)
	if err != nil {
		return netip.Addr{}, err
	}
	for _, ip := range ips {
		if v4 := ip.To4(); v4 != nil {
			a, _ := netip.AddrFromSlice(v4)
			return a, nil
		}
	}
	return netip.Addr{}, fmt.Errorf("no IPv4 address for %s", target)
}

// sendProbe owns one socket for one TTL: it sends a datagram, waits on the
// netpoller for the error queue to become readable, and classifies the error.
// The socket is closed before it returns, whatever the outcome.
func sendProbe(ctx context.Context, dst netip.Addr, ttl int, timeout time.Duration) probe {
	p := probe{TTL: ttl, Kind: kindSockErr}
	var optErr error
	d := net.Dialer{Control: func(_, _ string, c syscall.RawConn) error {
		return c.Control(func(fd uintptr) {
			if err := syscall.SetsockoptInt(int(fd), syscall.SOL_IP, syscall.IP_TTL, ttl); err != nil {
				optErr = fmt.Errorf("IP_TTL: %w", err)
				return
			}
			if err := syscall.SetsockoptInt(int(fd), syscall.SOL_IP, ipRecvErr, 1); err != nil {
				optErr = fmt.Errorf("IP_RECVERR: %w", err)
			}
		})
	}}
	conn, err := d.DialContext(ctx, "udp4", net.JoinHostPort(dst.String(), fmt.Sprint(basePort+ttl)))
	if optErr != nil {
		p.SockOpt = optErr.Error()
	}
	if err != nil {
		p.Detail = "dial: " + err.Error()
		if ctx.Err() != nil {
			p.Kind = kindCancelled
		}
		return p
	}
	defer conn.Close()
	uc := conn.(*net.UDPConn)
	stop := context.AfterFunc(ctx, func() { _ = uc.SetReadDeadline(time.Unix(1, 0)) })
	defer stop()

	sent := time.Now()
	if _, err := uc.Write([]byte("devdesk-nettrace-spike")); err != nil {
		p.Detail = "write: " + err.Error()
		return p
	}
	_ = uc.SetReadDeadline(sent.Add(timeout))
	rc, err := uc.SyscallConn()
	if err != nil {
		p.Detail = "syscallconn: " + err.Error()
		return p
	}
	oob := make([]byte, 512)
	buf := make([]byte, 512)
	var n, oobn int
	var rerr error
	err = rc.Read(func(fd uintptr) bool {
		for {
			n, oobn, _, _, rerr = syscall.Recvmsg(int(fd), buf, oob, syscall.MSG_ERRQUEUE|syscall.MSG_DONTWAIT)
			if rerr == syscall.EINTR {
				continue
			}
			return rerr != syscall.EAGAIN
		}
	})
	p.Latency = time.Since(sent)
	_ = n
	switch {
	case err != nil && ctx.Err() != nil:
		p.Kind = kindCancelled
		p.Latency = 0
	case errors.Is(err, os.ErrDeadlineExceeded):
		p.Kind = kindSilent
		p.Latency = 0
	case err != nil:
		p.Detail = "read: " + err.Error()
	case rerr != nil:
		p.Detail = "recvmsg: " + rerr.Error()
	default:
		classify(&p, oob[:oobn], dst)
	}
	return p
}

// classify decodes the sock_extended_err control message and the offender.
func classify(p *probe, oob []byte, dst netip.Addr) {
	msgs, err := syscall.ParseSocketControlMessage(oob)
	if err != nil {
		p.Detail = "cmsg: " + err.Error()
		return
	}
	for _, m := range msgs {
		if m.Header.Level != syscall.SOL_IP || m.Header.Type != ipRecvErr || len(m.Data) < 16 {
			continue
		}
		origin, typ, code := m.Data[4], int(m.Data[5]), int(m.Data[6])
		if len(m.Data) >= 24 && binary.NativeEndian.Uint16(m.Data[16:18]) == syscall.AF_INET {
			p.Addr, _ = netip.AddrFromSlice(m.Data[20:24])
		}
		p.Detail = fmt.Sprintf("origin=%d type=%d code=%d errno=%d", origin, typ, code, binary.NativeEndian.Uint32(m.Data[0:4]))
		if origin != soEeOriginICMP {
			p.Kind = kindSockErr
			return
		}
		switch {
		case typ == icmpTimeExceeded:
			p.Kind = kindTimeExceed
		case typ == icmpDestUnreach && code == icmpPortUnreach && p.Addr == dst:
			p.Kind = kindReached
		default:
			p.Kind = kindUnreach
			p.Code = typ*1000 + code
		}
		return
	}
	p.Detail = "no IP_RECVERR control message"
}

// ---------------------------------------------------------------- measures

type l6Result struct {
	Real      bool // measured on the real path
	PathHops  int  // hops of the real path, 0 when unknown
	Bound     int  // TTL bound used when not real
	Run       result
	Threshold time.Duration
}

func measureL6(main1 result, target string, timeout, deadline time.Duration) l6Result {
	l := l6Result{Threshold: 5 * time.Second}
	if main1.Outcome == outReached && len(main1.Hops) >= 8 {
		l.Real, l.PathHops, l.Run = true, len(main1.Hops), main1
		return l
	}
	if main1.Outcome == outReached {
		l.PathHops = len(main1.Hops)
	}
	l.Bound = 8
	l.Run = trace(context.Background(), target, 8, timeout, deadline)
	return l
}

type l5Result struct {
	Unreach   result // unreachable target, default TTL max
	TTLBound  result // reachable target, TTL max lowered to 5
	ShortDead result // unreachable target, deadline shorter than the probe timeout
}

func measureL5(target, unreach string, timeout time.Duration) l5Result {
	return l5Result{
		Unreach:   trace(context.Background(), unreach, hardMaxTTL, timeout, hardDeadline),
		TTLBound:  trace(context.Background(), target, 5, timeout, hardDeadline),
		ShortDead: trace(context.Background(), unreach, hardMaxTTL, 20*time.Second, 1500*time.Millisecond),
	}
}

type l7Result struct {
	Cycles                   int
	FdBefore, FdAfter        int
	FdMax                    int
	GoBefore, GoAfter, GoMax int
	MinPending               int
	Stops                    []time.Duration
	Err                      string
}

func countFds() int {
	ents, err := os.ReadDir("/proc/self/fd")
	if err != nil {
		return -1
	}
	return len(ents)
}

func measureL7(unreach string, cycles int, timeout time.Duration) l7Result {
	// Warm up so lazily created runtime goroutines are in the baseline.
	trace(context.Background(), unreach, 3, timeout, hardDeadline)
	time.Sleep(200 * time.Millisecond)
	l := l7Result{Cycles: cycles, FdBefore: countFds(), GoBefore: runtime.NumGoroutine(), MinPending: 1 << 30}
	l.FdMax, l.GoMax = l.FdBefore, l.GoBefore
	for i := 0; i < cycles; i++ {
		ctx, cancel := context.WithCancel(context.Background())
		var cancelledAt time.Time
		go func() {
			time.Sleep(150 * time.Millisecond)
			cancelledAt = time.Now()
			cancel()
		}()
		r := trace(ctx, unreach, hardMaxTTL, timeout, hardDeadline)
		end := time.Now()
		cancel()
		// cancelledAt is written before cancel() and read after trace
		// returned because of that cancel(), so it is ordered.
		if cancelledAt.IsZero() || r.Outcome != outCancelled {
			l.Err = fmt.Sprintf("cycle %d: trace ended with %q before cancellation", i, r.Outcome)
		} else {
			l.Stops = append(l.Stops, end.Sub(cancelledAt))
		}
		if r.Pending < l.MinPending {
			l.MinPending = r.Pending
		}
		l.FdMax = max(l.FdMax, countFds())
		l.GoMax = max(l.GoMax, runtime.NumGoroutine())
	}
	time.Sleep(200 * time.Millisecond)
	l.FdAfter, l.GoAfter = countFds(), runtime.NumGoroutine()
	return l
}

// ---------------------------------------------------------------- report

type report struct{ b strings.Builder }

func (r *report) String() string { return r.b.String() }
func (r *report) f(format string, a ...any) {
	fmt.Fprintf(&r.b, format, a...)
}

func readFirst(path, prefix string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		return "unreadable: " + err.Error()
	}
	for _, line := range strings.Split(string(data), "\n") {
		if prefix == "" {
			return strings.TrimSpace(line)
		}
		if v, ok := strings.CutPrefix(line, prefix); ok {
			return strings.Trim(strings.TrimSpace(v), `"`)
		}
	}
	return "not found"
}

func capEff() string { return readFirst("/proc/self/status", "CapEff:") }

func (r *report) header(target, unreach string, maxTTL int, timeout, deadline time.Duration, cycles int) {
	r.f("=== nettrace spike report (DEVDESK-385, S-01) ===\n")
	r.f("WARNING: this report contains the addresses of the routers on your path (private and public). Check it before pasting it anywhere.\n\n")
	r.f("time           : %s\n", time.Now().Format(time.RFC3339))
	r.f("commit         : %s\n", commit)
	r.f("os             : %s (%s/%s)\n", readFirst("/etc/os-release", "PRETTY_NAME="), runtime.GOOS, runtime.GOARCH)
	r.f("kernel         : %s\n", readFirst("/proc/sys/kernel/osrelease", ""))
	r.f("go             : %s\n", runtime.Version())
	r.f("uid            : %d (euid %d)\n", os.Getuid(), os.Geteuid())
	r.f("CapEff         : %s\n", capEff())
	r.f("PATH           : %q\n", os.Getenv("PATH"))
	r.f("WSL_DISTRO_NAME: %q\n", os.Getenv("WSL_DISTRO_NAME"))
	r.f("target         : %s\n", target)
	r.f("unreachable    : %s\n", unreach)
	r.f("max TTL        : %d\n", maxTTL)
	r.f("probe timeout  : %s\n", timeout)
	r.f("trace deadline : %s\n", deadline)
	r.f("L7 cycles      : %d\n\n", cycles)
}

func (r *report) printTrace(title string, t result) {
	r.f("--- %s: %s ---\n", title, t.Target)
	r.f("max TTL %d, probe timeout %s, duration %s, result: %s\n", t.MaxTTL, t.Timeout, t.Duration.Round(time.Millisecond), t.Outcome)
	r.f("%-4s %-16s %-10s %s\n", "TTL", "address", "latency", "state")
	for _, p := range t.Hops {
		addr := "*"
		if p.Addr.IsValid() {
			addr = p.Addr.String()
		}
		lat := "-"
		if p.Latency > 0 {
			lat = fmt.Sprintf("%.2fms", float64(p.Latency.Microseconds())/1000)
		}
		extra := p.Kind.String()
		if p.Kind == kindUnreach {
			extra = fmt.Sprintf("unreachable (icmp %d/%d)", p.Code/1000, p.Code%1000)
		}
		if p.SockOpt != "" {
			extra += " setsockopt-error: " + p.SockOpt
		}
		if p.Kind == kindSockErr {
			extra += " detail: " + p.Detail
		}
		r.f("%-4d %-16s %-10s %s\n", p.TTL, addr, lat, extra)
	}
	r.f("\n")
}

func (r *report) printL6(l l6Result) {
	r.f("--- L6 measurement ---\n")
	if l.Real {
		r.f("measured on the real path (%d hops >= 8): duration %s\n\n", l.PathHops, l.Run.Duration.Round(time.Millisecond))
		return
	}
	r.f("real path hops: %d (0 = unknown); TTL bounded to %d; result: %s; duration %s\n\n", l.PathHops, l.Bound, l.Run.Outcome, l.Run.Duration.Round(time.Millisecond))
}

func (r *report) printL5(l l5Result) {
	r.f("--- L5 measurements ---\n")
	for _, c := range []struct {
		name string
		t    result
	}{{"unreachable target, max TTL 30", l.Unreach}, {"reachable target, max TTL lowered to 5", l.TTLBound}, {"unreachable target, deadline 1.5s < probe timeout 20s", l.ShortDead}} {
		r.f("%-55s -> %-40s %s (target %s)\n", c.name, c.t.Outcome, c.t.Duration.Round(time.Millisecond), c.t.Target)
	}
	r.f("\n")
}

func median(d []time.Duration) time.Duration {
	if len(d) == 0 {
		return 0
	}
	s := append([]time.Duration(nil), d...)
	sort.Slice(s, func(i, j int) bool { return s[i] < s[j] })
	return s[len(s)/2]
}

func (r *report) printL7(l l7Result) {
	r.f("--- L7 measurement ---\n")
	r.f("cycles: %d (cancelled 150ms after start, unresolved probes at cancel: min %d)\n", l.Cycles, l.MinPending)
	r.f("fds       before %d, max during %d, after %d\n", l.FdBefore, l.FdMax, l.FdAfter)
	r.f("goroutines before %d, max during %d, after %d\n", l.GoBefore, l.GoMax, l.GoAfter)
	if len(l.Stops) > 0 {
		s := append([]time.Duration(nil), l.Stops...)
		sort.Slice(s, func(i, j int) bool { return s[i] < s[j] })
		r.f("stop delay after cancel: min %s, median %s, max %s\n", s[0], median(s), s[len(s)-1])
	}
	if l.Err != "" {
		r.f("error: %s\n", l.Err)
	}
	r.f("\n")
}

// ---------------------------------------------------------------- verdicts

func ok(b bool) string {
	if b {
		return "OK"
	}
	return "KO"
}

func (r *report) verdicts(m result, l6 l6Result, l5 l5Result, extras []result, l7 l7Result) {
	r.f("=== Verdicts of this run ===\n")

	// L1 (binary side). The os/exec import and the empty-PATH run are checked outside.
	sockOptErr := ""
	for _, t := range append([]result{m, l5.Unreach}, extras...) {
		for _, p := range t.Probes {
			if p.SockOpt != "" && sockOptErr == "" {
				sockOptErr = p.SockOpt
			}
		}
	}
	l1 := os.Geteuid() != 0 && capEff() == "0000000000000000" && sockOptErr == ""
	r.f("L1 %s  uid=%d CapEff=%s setsockopt-error=%q (os/exec import and empty-PATH run are checked outside the binary)\n", ok(l1), os.Geteuid(), capEff(), sockOptErr)

	// L2.
	answered, ordered, prev := 0, true, 0
	for _, p := range m.Hops {
		if p.Addr.IsValid() && (p.Kind == kindTimeExceed || p.Kind == kindReached || p.Kind == kindUnreach) {
			answered++
			if p.TTL <= prev {
				ordered = false
			}
			prev = p.TTL
		}
	}
	r.f("L2 %s  %d hops with an address (need >= 3), increasing TTL order: %v\n", ok(answered >= 3 && ordered), answered, ordered)

	// L3: replied probes woke up long before the read deadline.
	maxLat, replied := time.Duration(0), 0
	for _, p := range m.Probes {
		if p.Addr.IsValid() {
			replied++
			maxLat = max(maxLat, p.Latency)
		}
	}
	l3 := replied > 0 && maxLat < m.Timeout/2
	r.f("L3 %s  netpoller (RawConn.Read, no polling loop): %d replies, max wait %s vs read deadline %s\n", ok(l3), replied, maxLat.Round(time.Microsecond), m.Timeout)

	// L4: a silent TTL followed by a TTL that answers, on any traced path.
	l4src := ""
	for _, t := range append([]result{m}, extras...) {
		if hasSilentThenAnswer(t) {
			l4src = t.Target
			break
		}
	}
	if l4src != "" {
		r.f("L4 OK  silent hop followed by an answering hop on the path to %s\n", l4src)
	} else {
		r.f("L4 NOT EVALUATED  no silent hop followed by an answering hop on the traced paths\n")
	}

	// L5.
	l5ok := l5.Unreach.Outcome == outTTLMax && l5.Unreach.Duration <= hardDeadline &&
		l5.TTLBound.Outcome == outTTLMax && l5.ShortDead.Outcome == outDelay && l5.ShortDead.Duration <= hardDeadline
	r.f("L5 %s  unreachable: %s in %s; TTL max: %s in %s; delay: %s in %s\n", ok(l5ok),
		l5.Unreach.Outcome, l5.Unreach.Duration.Round(time.Millisecond),
		l5.TTLBound.Outcome, l5.TTLBound.Duration.Round(time.Millisecond),
		l5.ShortDead.Outcome, l5.ShortDead.Duration.Round(time.Millisecond))

	// L6.
	r.f("L6 %s  %s (threshold %s, real path: %v, bound: %d)\n", ok(l6.Run.Duration < l6.Threshold), l6.Run.Duration.Round(time.Millisecond), l6.Threshold, l6.Real, l6.Bound)

	// L7.
	l7ok := l7.Err == "" && l7.FdAfter == l7.FdBefore && l7.GoAfter == l7.GoBefore && l7.FdMax <= l7.FdBefore && l7.MinPending >= 1
	r.f("L7 %s  fds %d -> %d (max %d), goroutines %d -> %d, %d cycles\n", ok(l7ok), l7.FdBefore, l7.FdAfter, l7.FdMax, l7.GoBefore, l7.GoAfter, l7.Cycles)
	r.f("=== end of report ===\n")
}

func hasSilentThenAnswer(t result) bool {
	silent := false
	for _, p := range t.Hops {
		switch {
		case p.Kind == kindSilent:
			silent = true
		case silent && p.Addr.IsValid():
			return true
		}
	}
	return false
}

